public class Main {
    static int n, m;
    static int cells;
    static int[] dx = {0, 0, 0, 1, -1}; // stay, L, R, D, U
    static int[] dy = {0, -1, 1, 0, 0};
    static int[][] id;
    static int[] spiderCell; // starting cell index for each spider (same as cell index)
    static int[] moveDir;    // chosen move direction for each spider (0..4)
    static int bestFree = 0;

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        m = Integer.parseInt(st.nextToken());
        cells = n * m;
        id = new int[n][m];
        int idx = 0;
        for (int i = 0; i < n; i++)
            for (int j = 0; j < m; j++)
                id[i][j] = idx++;

        spiderCell = new int[cells];
        moveDir = new int[cells];
        for (int i = 0; i < cells; i++) spiderCell[i] = i;

        dfs(0);
        System.out.println(bestFree);
    }

    static void dfs(int pos) {
        if (pos == cells) {
            int[] cnt = new int[cells];
            for (int s = 0; s < cells; s++) {
                int cell = spiderCell[s];
                int x = cell / m;
                int y = cell % m;
                int dir = moveDir[s];
                int nx = x + dx[dir];
                int ny = y + dy[dir];
                int dest = id[nx][ny];
                cnt[dest]++;
            }
            int free = 0;
            for (int i = 0; i < cells; i++)
                if (cnt[i] == 0) free++;
            if (free > bestFree) bestFree = free;
            return;
        }

        int cell = spiderCell[pos];
        int x = cell / m;
        int y = cell % m;

        // stay
        moveDir[pos] = 0;
        dfs(pos + 1);

        // left
        if (y > 0) {
            moveDir[pos] = 1;
            dfs(pos + 1);
        }
        // right
        if (y + 1 < m) {
            moveDir[pos] = 2;
            dfs(pos + 1);
        }
        // down
        if (x + 1 < n) {
            moveDir[pos] = 3;
            dfs(pos + 1);
        }
        // up
        if (x > 0) {
            moveDir[pos] = 4;
            dfs(pos + 1);
        }
    }
}

