public class Main {
    static int n, m;
    static int cells;
    static int[] dx = {0, 0, 0, 1, -1}; // stay, L, R, D, U
    static int[] dy = {0, -1, 1, 0, 0};
    static int[][] id; // cell index
    static int[] x, y; // coordinates by index

    static int best = 0;

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        m = Integer.parseInt(st.nextToken());
        cells = n * m;

        id = new int[n][m];
        x = new int[cells];
        y = new int[cells];
        int idx = 0;
        for (int i = 0; i < n; i++)
            for (int j = 0; j < m; j++) {
                id[i][j] = idx;
                x[idx] = i;
                y[idx] = j;
                idx++;
            }

        // backtracking over assignments of commands to each spider
        int[] dest = new int[cells];
        dfs(0, dest);
        System.out.println(best);
    }

    static void dfs(int pos, int[] dest) {
        if (pos == cells) {
            // count occupied cells
            boolean[] occ = new boolean[cells];
            for (int i = 0; i < cells; i++) occ[dest[i]] = true;
            int occupied = 0;
            for (int i = 0; i < cells; i++) if (occ[i]) occupied++;
            int free = cells - occupied;
            if (free > best) best = free;
            return;
        }

        int cx = x[pos];
        int cy = y[pos];

        // try all 5 commands, but only valid moves
        for (int k = 0; k < 5; k++) {
            int nx = cx + dx[k];
            int ny = cy + dy[k];
            if (nx < 0 || nx >= n || ny < 0 || ny >= m) continue;
            dest[pos] = id[nx][ny];
            dfs(pos + 1, dest);
        }
    }
}

import java.io.*;
