public class Main {
    static int n, m;
    static int cells;
    static int[][] id; // cell index
    static int V;      // number of vertices = n*m
    static boolean[][] adj; // adjacency matrix
    static int[] match;     // match[v] = u or -1
    static boolean[] used;  // used in DFS

    static boolean dfs(int v) {
        for (int u = 0; u < V; u++) {
            if (adj[v][u] && !used[u]) {
                used[u] = true;
                if (match[u] == -1 || dfs(match[u])) {
                    match[u] = v;
                    return true;
                }
            }
        }
        return false;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        m = Integer.parseInt(st.nextToken());
        cells = n * m;
        V = cells;
        id = new int[n][m];
        int idx = 0;
        for (int i = 0; i < n; i++)
            for (int j = 0; j < m; j++)
                id[i][j] = idx++;

        adj = new boolean[V][V];

        int[] dx = {0, 0, 1, -1};
        int[] dy = {1, -1, 0, 0};

        // Build adjacency: edge between cells that are neighbors
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int a = id[i][j];
                for (int k = 0; k < 4; k++) {
                    int ni = i + dx[k];
                    int nj = j + dy[k];
                    if (ni >= 0 && ni < n && nj >= 0 && nj < m) {
                        int b = id[ni][nj];
                        adj[a][b] = true;
                    }
                }
            }
        }

        match = new int[V];
        Arrays.fill(match, -1);

        int matchingSize = 0;
        for (int v = 0; v < V; v++) {
            used = new boolean[V];
            if (dfs(v)) matchingSize++;
        }

        int maxSpiderFree = cells - matchingSize;
        System.out.println(maxSpiderFree);
    }
}

