public class Main {
    static int n, m;
    static int cells;
    static int[][] id;          // cell index
    static int[][] varIdx;      // variable index for each spider (cell)
    static int varCount;
    static int[][][] moveTo;    // moveTo[i][j][dir] = target cell index or -1
    static int[] dx = {0, 0, 1, -1};
    static int[] dy = {1, -1, 0, 0};

    static int best;

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        m = Integer.parseInt(st.nextToken());
        cells = n * m;

        id = new int[n][m];
        int idx = 0;
        for (int i = 0; i < n; i++)
            for (int j = 0; j < m; j++)
                id[i][j] = idx++;

        varIdx = new int[n][m];
        varCount = cells; // one variable per spider (cell)
        for (int i = 0; i < n; i++)
            for (int j = 0; j < m; j++)
                varIdx[i][j] = id[i][j];

        moveTo = new int[n][m][5]; // 0: stay, 1..4: directions
        for (int i = 0; i < n; i++)
            for (int j = 0; j < m; j++) {
                // stay
                moveTo[i][j][0] = id[i][j];
                // right
                moveTo[i][j][1] = (j + 1 < m) ? id[i][j + 1] : -1;
                // left
                moveTo[i][j][2] = (j - 1 >= 0) ? id[i][j - 1] : -1;
                // down
                moveTo[i][j][3] = (i + 1 < n) ? id[i + 1][j] : -1;
                // up
                moveTo[i][j][4] = (i - 1 >= 0) ? id[i - 1][j] : -1;
            }

        best = 0;

        // Backtracking over all spiders, each chooses one of valid moves
        int[] chosenMove = new int[cells];
        dfs(0, chosenMove);

        System.out.println(best);
    }

    static void dfs(int pos, int[] chosenMove) {
        if (pos == cells) {
            int[] cnt = new int[cells];
            for (int i = 0; i < cells; i++) {
                int r = i / m;
                int c = i % m;
                int dir = chosenMove[i];
                int to = moveTo[r][c][dir];
                if (to >= 0) cnt[to]++;
                else cnt[id[r][c]]++; // should not happen due to filtering
            }
            int empty = 0;
            for (int i = 0; i < cells; i++)
                if (cnt[i] == 0) empty++;
            if (empty > best) best = empty;
            return;
        }

        int r = pos / m;
        int c = pos % m;

        // Try all valid moves (including stay)
        for (int d = 0; d < 5; d++) {
            if (moveTo[r][c][d] == -1) continue; // invalid (would leave board)
            chosenMove[pos] = d;
            dfs(pos + 1, chosenMove);
        }
    }
}

