public class Main {
    static int n, m;
    static int cells;
    static int[] dx = {0, 0, 0, 1, -1}; // stay, L, R, D, U
    static int[] dy = {0, -1, 1, 0, 0};
    static int[][] id;
    static int[] comp; // command per cell (0..4)
    static int best;

    static boolean validMove(int x, int y, int cmd) {
        int nx = x + dx[cmd];
        int ny = y + dy[cmd];
        return nx >= 0 && nx < n && ny >= 0 && ny < m;
    }

    static int computeFree() {
        boolean[] occupied = new boolean[cells];
        for (int x = 0; x < n; x++) {
            for (int y = 0; y < m; y++) {
                int idx = id[x][y];
                int cmd = comp[idx];
                int nx = x + dx[cmd];
                int ny = y + dy[cmd];
                int to = id[nx][ny];
                occupied[to] = true;
            }
        }
        int free = 0;
        for (int i = 0; i < cells; i++) if (!occupied[i]) free++;
        return free;
    }

    static void dfs(int pos) {
        if (pos == cells) {
            int free = computeFree();
            if (free > best) best = free;
            return;
        }
        int x = pos / m;
        int y = pos % m;
        for (int cmd = 0; cmd < 5; cmd++) {
            if (!validMove(x, y, cmd)) continue;
            comp[pos] = cmd;
            dfs(pos + 1);
        }
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        m = Integer.parseInt(st.nextToken());
        cells = n * m;
        id = new int[n][m];
        int cnt = 0;
        for (int i = 0; i < n; i++)
            for (int j = 0; j < m; j++)
                id[i][j] = cnt++;
        comp = new int[cells];
        best = 0;
        dfs(0);
        System.out.println(best);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static int n, m;
    static int cells;
    static int[][] id;          // cell index
    static int[][] varId;       // variable index for each cell and direction
    static int varCount;
    static List<Integer>[] g;   // implication graph
    static List<Integer>[] gr;  // reverse graph

    static int idx(int v, boolean neg) {
        return v * 2 + (neg ? 1 : 0);
    }

    static void addImplication(int a, boolean na, int b, boolean nb) {
        int x = idx(a, na);
        int y = idx(b, nb);
        g[x].add(y);
        gr[y].add(x);
    }

    static void addOr(int a, boolean na, int b, boolean nb) {
        // (a v b) == (~a -> b) & (~b -> a)
        addImplication(a, !na, b, nb);
        addImplication(b, !nb, a, na);
    }

    static void addUnit(int a, boolean na) {
        // a must be na: (~a -> a)
        addImplication(a, !na, a, na);
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        m = Integer.parseInt(st.nextToken());
        cells = n * m;
        id = new int[n][m];
        int c = 0;
        for (int i = 0; i < n; i++)
            for (int j = 0; j < m; j++)
                id[i][j] = c++;

        // directions: 0=U,1=D,2=L,3=R
        varId = new int[n][m * 4];
        varCount = 0;
        for (int i = 0; i < n; i++)
            for (int j = 0; j < m; j++)
                for (int d = 0; d < 4; d++)
                    varId[i][j * 4 + d] = varCount++;

        int totalVars = varCount;
        int N = totalVars * 2;
        g = new ArrayList[N];
        gr = new ArrayList[N];
        for (int i = 0; i < N; i++) {
            g[i] = new ArrayList<>();
            gr[i] = new ArrayList<>();
        }

        // For each cell, exactly one of {stay, U,D,L,R} is chosen.
        // We model only movement vars; "stay" is implicit.
        // At most one movement: pairwise not both true.
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int[] v = new int[4];
                for (int d = 0; d < 4; d++) v[d] = varId[i][j * 4 + d];
                for (int a = 0; a < 4; a++)
                    for (int b = a + 1; b < 4; b++)
                        addOr(v[a], false, v[b], false); // !va or !vb

                // boundary: forbid moves that go outside
                if (i == 0) addUnit(varId[i][j * 4 + 0], false); // !U
                if (i == n - 1) addUnit(varId[i][j * 4 + 1], false); // !D
                if (j == 0) addUnit(varId[i][j * 4 + 2], false); // !L
                if (j == m - 1) addUnit(varId[i][j * 4 + 3], false); // !R
            }
        }

        // For each cell, at most one spider ends there.
        // For each pair of incoming moves to same cell, not both true.
        int[] di = {-1, 1, 0, 0};
        int[] dj = {0, 0, -1, 1};
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                List<Integer> incoming = new ArrayList<>();
                // from neighbors
                for (int d = 0; d < 4; d++) {
                    int ni = i + di[d];
                    int nj = j + dj[d];
                    if (ni >= 0 && ni < n && nj >= 0 && nj < m) {
                        int fromVar = varId[ni][nj * 4 + (d ^ 1)]; // opposite dir
                        incoming.add(fromVar);
                    }
                }
                // staying spiders: we don't have explicit vars; but "stay" is allowed.
                // To maximize empty cells, we must ensure at most one spider ends here:
                // if any movement comes, then others (including stay) must be false.
                // This is not directly expressible with stay var absent, but we can
                // enforce that if any movement is chosen, no other movement is.
                for (int a = 0; a < incoming.size(); a++)
                    for (int b = a + 1; b < incoming.size(); b++)
                        addOr(incoming.get(a), false, incoming.get(b), false); // !va or !vb
            }
        }

        // 2-SAT via Kosaraju
        int[] order = new int[N];
        boolean[] used = new boolean[N];
        int ptr = 0;

        for (int i = 0; i < N; i++)
            if (!used[i]) {
                Deque<Integer> stack = new ArrayDeque<>();
                Deque<Integer> call = new ArrayDeque<>();
                call.push(i);
                while (!call.isEmpty()) {
                    int v = call.peek();
                    if (!used[v]) {
                        used[v] = true;
                        for (int to : g[v])
                            if (!used[to]) call.push(to);
                    } else {
                        call.pop();
                        order[ptr++] = v;
                    }
                }
            }

        int[] comp = new int[N];
        Arrays.fill(comp, -1);
        int j = 0;
        for (int i = N - 1; i >= 0; i--) {
            int v = order[i];
            if (comp[v] == -1) {
                Deque<Integer> stack = new ArrayDeque<>();
                stack.push(v);
                comp[v] = j;
                while (!stack.isEmpty()) {
                    int x = stack.pop();
                    for (int to : gr[x])
                        if (comp[to] == -1) {
                            comp[to] = j;
                            stack.push(to);
                        }
                }
                j++;
            }
        }

        boolean[] val = new boolean[totalVars];
        for (int v = 0; v < totalVars; v++) {
            if (comp[2 * v] == comp[2 * v + 1]) {
                // unsat; but constraints should be satisfiable
            }
            val[v] = comp[2 * v] > comp[2 * v + 1];
        }

        // Count empty cells: cell is empty if no spider ends there.
        int empty = 0;
        for (int i = 0; i < n; i++) {
            for (int j2 = 0; j2 < m; j2++) {
                boolean occupied = false;
                // check incoming moves
                for (int d = 0; d < 4; d++) {
                    int ni = i + di[d];
                    int nj = j2 + dj[d];
                    if (ni >= 0 && ni < n && nj >= 0 && nj < m) {
                        int fromVar = varId[ni][nj * 4 + (d ^ 1)];
                        if (val[fromVar]) {
                            occupied = true;
                            break;
                        }
                    }
                }
                // if no incoming move, spider may stay; but to maximize emptiness,
                // we assume it stays only if forced by constraints. Our model
                // doesn't force staying, so we treat no incoming as empty.
                if (!occupied) empty++;
            }
        }

        System.out.println(empty);
    }
}
